import AppKit
import Combine

enum ClipboardReader {
    static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword"
    ]

    static func read(_ pasteboard: NSPasteboard, source: String) -> ClipboardEntry? {
        let allTypes = Set((pasteboard.types ?? []).map(\.rawValue))
            .union((pasteboard.pasteboardItems ?? []).flatMap { $0.types.map(\.rawValue) })
        guard allTypes.isDisjoint(with: ignoredTypes), !allTypes.contains(NSPasteboard.PasteboardType.fileURL.rawValue),
              let item = pasteboard.pasteboardItems?.first else { return nil }
        // A history item is a single text or image. Do not silently truncate multi-item file copies.
        guard pasteboard.pasteboardItems?.count == 1 else { return nil }
        let text = item.string(forType: .string) ?? ""
        let imageType: NSPasteboard.PasteboardType? = item.types.contains(.png) ? .png : (item.types.contains(.tiff) ? .tiff : nil)
        let types: [NSPasteboard.PasteboardType]
        if let imageType { types = [imageType] }
        else {
            guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return nil }
            types = [.string, .rtf, .html]
        }
        var representations: [ClipboardRepresentation] = []
        var total = 0
        for type in types where item.types.contains(type) {
            guard let data = item.data(forType: type) else { continue }
            total += data.count
            guard total <= HistoryStore.maxItemBytes else { return nil }
            representations.append(ClipboardRepresentation(type: type.rawValue, data: data))
        }
        guard !representations.isEmpty else { return nil }
        return ClipboardEntry(text: imageType == nil ? text : "이미지", isImage: imageType != nil,
                              source: source, representations: representations)
    }

    @discardableResult
    static func write(_ entry: ClipboardEntry, to pasteboard: NSPasteboard, plainText: Bool = false) -> Bool {
        let item = NSPasteboardItem()
        if plainText && !entry.isImage {
            item.setString(entry.text, forType: .string)
        } else {
            for representation in entry.representations {
                item.setData(representation.data, forType: .init(representation.type))
            }
        }
        pasteboard.clearContents()
        return pasteboard.writeObjects([item])
    }
}

final class ClipboardMonitor: ObservableObject {
    @Published private(set) var clipboardAccessDenied = false
    @Published var isPaused = false {
        didSet { lastChangeCount = pasteboard.changeCount }
    }
    private let store: HistoryStore
    private let pasteboard: NSPasteboard
    private var lastChangeCount: Int
    private var timer: Timer?

    init(store: HistoryStore, pasteboard: NSPasteboard = .general) {
        self.store = store
        self.pasteboard = pasteboard
        self.lastChangeCount = pasteboard.changeCount
    }

    func start() {
        guard timer == nil else { return }
        let timer = Timer(timeInterval: 0.4, repeats: true) { [weak self] _ in self?.poll() }
        timer.tolerance = 0.1
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    func poll() {
        if #available(macOS 15.4, *) {
            let denied = pasteboard.accessBehavior == .alwaysDeny
            if clipboardAccessDenied != denied { clipboardAccessDenied = denied }
        }
        let count = pasteboard.changeCount
        guard count != lastChangeCount else { return }
        // Leave the change pending so allowing access can capture the most recent copy.
        guard !clipboardAccessDenied else { return }
        lastChangeCount = count
        guard !isPaused else { return }
        let source = NSWorkspace.shared.frontmostApplication?.localizedName ?? ""
        if let entry = ClipboardReader.read(pasteboard, source: source), pasteboard.changeCount == count {
            store.add(entry)
        }
    }

    @discardableResult
    func restore(_ entry: ClipboardEntry, plainText: Bool = false) -> Bool {
        let success = ClipboardReader.write(entry, to: pasteboard, plainText: plainText)
        lastChangeCount = pasteboard.changeCount
        return success
    }

    deinit { timer?.invalidate() }
}
